		                                const cur = new Set(s.applicationsImpacted || []);
		                                if (on) cur.add(opt);
		                               else cur.delete(opt);
		                                return { ...s, applicationsImpacted: Array.from(cur) };
		                              });
		                            }}
		                          />
		                          <span>{opt}</span>
		                        </label>
		                      ))}
		                      
							   {/* keep the small adder (optional) */}
							  
		                      <div className="flex items-center gap-2 mt-2">
		                        <input
		                          className={inputCls}
		                          placeholder="Add application…"
		                          value={newAppValue}
